{
  "eventType": "COLLISION",
  "summary": "环岛内连环碰撞，发生于施工借道段（晴），涉及匝道汇流冲突，自动驾驶状态L2_ASSIST",
  "severity": "MEDIUM",
  "rootCause": "匝道汇流冲突导致连环碰撞"
}

{
  "eventType": "COLLISION",
  "summary": "匝道末端减速不及",
  "severity": "MEDIUM",
  "context": {
    "location": "隧道入口",
    "weather": "小雨",
    "involved": "慢车占道",
    "autonomyState": "AUTONOMOUS"
  },
  "rootCause": "车辆未能及时减速以应对匝道末端和前方慢车"
}

{
  "summary": "NOA异常退出未提示，发生于园区内部路（侧风偏大），右侧车辆强行切入，自动驾驶状态AUTONOMOUS，严重程度HIGH。",
  "rootCause": "NOA系统在侧风偏大且右侧车辆强行切入时异常退出，未提供提示信息。"
}

{
  "summary": "自动驾驶系统在高架匝道（雾）环境下，因感知误检导致误制动，车辆在前车急刹制动灯亮起时错误触发制动，影响行车安全。",
  "rootCause": "感知模块误检，将正常场景错误识别为需要紧急制动的危险场景。"
}

{
  "summary": "自动驾驶状态在长下坡接弯处（有雾）因外卖非机动车占道导致规划轨迹突变，触发AUTOPILOT_FAULT事件，等级HIGH，严重程度HIGH",
  "rootCause": "外卖非机动车占道导致规划轨迹突变"
}

{
  "summary": "雨雾视距不足仍高速接近导致驾驶员反应慢，施工借道段雾天锥桶偏移，自动驾驶L2_ASSIST状态下发生中等严重事故",
  "rootCause": "驾驶员在雨雾天气视距不足的情况下仍以较高速度接近施工区域，未能及时识别偏移的施工锥桶并采取减速或避让措施"
}

{
  "summary": "匝道汇流未预留时距导致自动驾驶辅助状态下追尾静止排队车龙末端，发生于晴天城市主干道。",
  "rootCause": "驾驶员反应迟缓，未及时预判车龙末端并预留安全时距。"
}

{
  "eventType": "AEB_DELAY_OR_MISS",
  "summary": "施工区域未减速",
  "rootCause": "行人突然横穿，自动驾驶未能及时制动",
  "severity": "HIGH"
}

{
  "eventType": "TTC_LOW_RISK",
  "summary": "拥堵跟车时距 <1.2s，TTC_LOW_RISK，HIGH等级；发生于城市主干道（多云），涉及前车急刹制动灯亮起，自动驾驶状态MANUAL",
  "severity": "HIGH",
  "rootCause": "跟车时距过小，导致前车急刹时无法安全避让"
}

{
  "summary": "在高架匝道（小雨）弯道出口处，因前方车辆减速未打灯，本车触发TTC_LOW_RISK预警，等级MEDIUM，自动驾驶状态MANUAL，严重程度MEDIUM。",
  "rootCause": "前方车辆在弯道出口突然减速且未开启转向灯，导致本车与前车距离快速缩短，触发低风险碰撞时间预警。",
  "impact": "未发生实际碰撞，但造成短暂的行车风险，驾驶员需紧急介入。",
  "recommendations": "建议驾驶员在弯道出口提前预判前车行为，保持安全跟车距离，并注意小雨天气下的制动距离增加。"
}

{
  "summary": "系统请求接管后5秒内驾驶员未接管，导致DRIVER_TAKEOVER_FAIL事件，发生于城市主干道（晴天），前车急刹制动灯亮起，自动驾驶状态为AUTONOMOUS，严重程度HIGH。",
  "rootCause": "驾驶员未能在系统请求接管后的5秒内响应，可能由于注意力不集中或未及时处理接管请求。",
  "severity": "HIGH",
  "incidentType": "DRIVER_TAKEOVER_FAIL"
}

{
  "summary": "在城市主干道侧风偏大条件下，车辆处于L2级别辅助驾驶状态，相邻车道变道挤压导致需要驾驶员接管，但驾驶员双手脱离方向盘，未能成功接管，发生DRIVER_TAKEOVER_FAIL事件，等级MEDIUM。",
  "rootCause": "驾驶员在需要接管时双手脱离方向盘，未能及时响应接管请求。",
  "severity": "MEDIUM",
  "eventType": "DRIVER_TAKEOVER_FAIL"
}

{
  "summary": "在长下坡接弯且有雾的路段，路面存在抛洒物，自动驾驶处于L2_ASSIST状态。驾驶员接管后方向修正过量，导致事故。",
  "eventType": "DRIVER_TAKEOVER_FAIL",
  "severity": "LOW",
  "rootCause": "驾驶员接管后方向修正过量"
}

{
  "summary": "在施工借道段（多云）自动驾驶状态下，因前车急刹制动灯亮起，驾驶员误踩加速踏板导致接管失败",
  "rootCause": "驾驶员误踩加速踏板",
  "eventType": "DRIVER_TAKEOVER_FAIL",
  "severity": "HIGH"
}

{
  "summary": "在城市主干道（多云）自动驾驶状态下，因前方车辆急刹导致制动灯亮起，本车在积水路面发生水滑，造成环境干扰事故，严重程度高。",
  "rootCause": "积水路面导致轮胎与地面附着力降低，叠加前车急刹触发制动，车辆失控水滑。"
}

{
  "eventType": "ENVIRONMENT_DISTURB",
  "summary": "夜间无照明行人横穿，快速路大雨，前方车辆减速未打灯，自动驾驶状态",
  "severity": "MEDIUM",
  "rootCause": "前方车辆减速未打灯，行人横穿导致环境干扰"
}

{
  "summary": "在冰雪覆盖的快速路上，因施工改道导致车道变更，叠加感知系统降级，驾驶员分心未及时应对，在匝道汇流处发生冲突，事故等级为MEDIUM。",
  "rootCause": "施工改道与冰雪环境导致道路条件复杂，感知系统降级未能提供有效预警，驾驶员分心未能及时干预。"
}

{
  "summary": "夜间施工借道段，因对向车辆眩光干扰，驾驶员未及时发现前方非机动车占道，加之L2辅助驾驶系统对静止障碍物识别延迟，前车急刹时制动灯亮起但本车未能有效避让，导致追尾事故。",
  "rootCause": "夜间眩光导致的驾驶员视觉盲区与L2系统对非机动车等异形障碍物的感知局限共同作用。",
  "eventType": "MULTI_FACTOR",
  "severity": "HIGH",
  "contributingFactors": {
    "environment": "夜间、施工借道段、对向车辆眩光",
    "roadUser": "非机动车占道行驶",
    "vehicle": "前车急刹，本车L2辅助驾驶状态",
    "human": "驾驶员受眩光影响反应延迟"
  }
}

{
  "eventType": "MULTI_FACTOR",
  "severity": "HIGH",
  "environment": {
    "roadType": "城市主干道",
    "weather": "小雨"
  },
  "vehicleState": "AUTONOMOUS",
  "summary": "多车交互过程中，前车急刹制动灯亮起，由于信号延迟导致本车制动不足，发生追尾或碰撞风险。",
  "rootCause": "多车交互、信号延迟、制动不足"
}
